// Determine briefing type based on which trigger fired
const isMonday = new Date().getDay() === 1;
const hour = new Date().getHours();

// Determine time range: weekly on Monday 7AM, daily otherwise
const isWeekly = isMonday && hour === 7;
const lookbackHours = isWeekly ? 168 : 24; // 7 days or 24 hours

return [{
  json: {
    briefing_type: isWeekly ? 'weekly' : 'daily',
    lookback_hours: lookbackHours,
    lookback_label: isWeekly ? 'last 7 days' : 'last 24 hours',
    briefing_date: new Date().toISOString().split('T')[0],
    triggered_at: new Date().toISOString()
  }
}];

// Aggregate all data for briefing agent
const briefingMeta = $('Determine Briefing Type').first().json;
const signals = $('Fetch Top Signals').all().map(i => i.json);
const trends = $('Fetch Top Trends by Momentum').all().map(i => i.json);
const competitorEvents = $('Fetch Competitor Events').all().map(i => i.json);

return [{
  json: {
    briefing_type: briefingMeta.briefing_type,
    briefing_date: briefingMeta.briefing_date,
    lookback_label: briefingMeta.lookback_label,
    data: {
      signals,
      trends,
      competitor_events: competitorEvents,
      summary_stats: {
        total_signals: signals.length,
        critical_signals: signals.filter(s => s.severity === 'critical').length,
        high_signals: signals.filter(s => s.severity === 'high').length,
        active_trends: trends.length,
        competitor_events: competitorEvents.length
      }
    },
    aggregated_at: new Date().toISOString()
  }
}];

